// blinky: top level generated by Weft — 1 clock domain, 0 native cells
// Clocks are top-level inputs (PLL primitives are not emitted); rst is synchronous and active high.
module blinky (
  input  wire [0:0] clk_sys,
  input  wire [0:0] rst,
  output wire [0:0] led
);
  wire [0:0] sys__o_pin_led_0;
  assign led[0] = sys__o_pin_led_0[0];
  blinky_sys u_sys (
    .clk(clk_sys),
    .rst(rst),
    .o_pin_led_0(sys__o_pin_led_0)
  );
endmodule
